```yaml
name: Remove SLO label after SLO workflow

on:
  workflow_run:
    workflows: ["SLO"]
    types: [completed]

permissions:
  contents: read
  issues: write

jobs:
  remove-slo-label:
    if: github.event.workflow_run.head_repository.fork == false
    runs-on: ubuntu-latest
    steps:
      - name: Remove SLO label
        uses: actions/github-script@v7
        with:
          script: |
            const pr = github.event.workflow_run.pull_requests?.[0];
            if (!pr) {
              core.info('No pull request found for this workflow run.');
              return;
            }
            const prNumber = pr.number;
            try {
              await github.rest.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                name: 'SLO',
              });
              core.info(`Removed SLO label from PR #${prNumber}`);
            } catch (error) {
              if (error.status === 404) {
                core.info(`SLO label not present on PR #${prNumber}`);
              } else {
                throw error;
              }
            }
